import { useEffect, useMemo, useState } from "react";
import { useQueryClient } from "@tanstack/react-query";
import { useLocation, useParams, Link } from "wouter";
import { Activity, ArrowUpRight, AudioWaveform, Check, ChevronDown, CircleAlert, Clock3, Copy, Cpu, Download, FileText, Film, HardDrive, KeyRound, Layers3, LockKeyhole, MoreHorizontal, Pause, Play, Plus, RefreshCw, Search, Server, ShieldCheck, SlidersHorizontal, Sparkles, Trash2, Upload, UserRound, Volume2, WandSparkles, WifiOff, X } from "lucide-react";
import { getGetModelInstallQueryKey, getGetSystemReadinessQueryKey, getListModelsQueryKey, getListProvidersQueryKey, useApproveModelInstall, useCancelRenderJob, useCreateBridgePairing, useCreateProject, useCreateProjectPlan, useCreateRenderJob, useDeleteProject, useGetActivity, useGetModelInstall, useGetProject, useGetProjectPlan, useGetStudioOverview, useGetSystemReadiness, useHealthCheck, useInstallModel, useListModels, useListProjects, useListProviders, useListRenderJobs, useListStudioAssets, useRequestProviderCredential, useRetryModelInstall, useScanSystemReadiness, useUpdateProject, useUpdateProjectPlan, useUpdateProvider } from "@workspace/api-client-react";
import { BackLink, Button, EmptyState, ErrorState, LoadingState, Metric, PageHeader, SectionLabel, StatusPill } from "@/components/studio-shell";

function formatDuration(seconds = 0) { const m = Math.floor(seconds / 60); const s = seconds % 60; return `${m}:${String(s).padStart(2, "0")}`; }
function timeAgo(date?: string) { if (!date) return "just now"; const mins = Math.max(1, Math.floor((Date.now() - new Date(date).getTime()) / 60000)); return mins < 60 ? `${mins}m ago` : `${Math.floor(mins / 60)}h ago`; }
function QueryMessage({ isLoading, isError, refetch, children }: { isLoading: boolean; isError: boolean; refetch: () => void; children: React.ReactNode }) { if (isLoading) return <LoadingState />; if (isError) return <ErrorState retry={refetch} />; return <>{children}</>; }

export function OverviewPage() {
  const health = useHealthCheck(); const overview = useGetStudioOverview(); const activity = useGetActivity(); const readiness = useGetSystemReadiness();
  return <><PageHeader eyebrow="01 / command center" title="Production, at a glance." description="A local-first control surface for scripts, voices, presenters, and final delivery." action={<Link href="/projects" className="inline-flex items-center gap-2 rounded-md bg-primary px-4 py-2.5 text-xs font-semibold text-primary-foreground hover:brightness-110" data-testid="link-new-production"><Plus size={15} /> New production</Link>} />
    <QueryMessage isLoading={overview.isLoading} isError={overview.isError} refetch={overview.refetch}>{overview.data && <div className="studio-in">
      <div className="mb-4 flex items-center gap-2 text-[11px] text-muted-foreground"><span className={`h-1.5 w-1.5 rounded-full ${health.data?.status === "ok" ? "bg-accent" : health.isError ? "bg-red-300" : "bg-primary"}`} /> Service health: <span className="font-mono uppercase tracking-wider">{health.isLoading ? "checking" : health.data?.status ?? "offline"}</span></div><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Active productions" value={overview.data.activeProjects} detail="Across your workspace" /><Metric label="Render queue" value={overview.data.renderQueue} detail={overview.data.currentTask ?? "Queue is clear"} accent /><Metric label="Local models" value={overview.data.installedModels} detail="Ready for inference" /><Metric label="GPU memory" value={overview.data.gpuMemory} detail="Unified memory allocation" /></div>
      <div className="mt-7 grid gap-6 xl:grid-cols-[1.35fr_.65fr]">
        <div><SectionLabel right={<Link href="/render" className="text-xs text-primary hover:underline" data-testid="link-view-render-queue">View render queue <ArrowUpRight className="inline" size={13} /></Link>}>Live workload</SectionLabel><div className="rounded-lg border border-border bg-card p-5"><div className="flex items-start justify-between gap-4"><div><p className="text-xs text-muted-foreground">Current task</p><h3 className="mt-1 font-serif text-xl font-bold">{overview.data.currentTask ?? "No active task"}</h3></div><StatusPill status={overview.data.readiness} /></div><div className="mt-7 h-2 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-primary transition-all duration-700" style={{ width: overview.data.renderQueue ? "8%" : "0%" }} /></div><div className="mt-2 flex justify-between font-mono text-[10px] text-muted-foreground"><span>{overview.data.renderQueue ? "Local worker waiting" : overview.data.readinessLabel}</span><span>{overview.data.renderQueue ? "queued" : "standby"}</span></div></div>
          <div className="mt-6"><SectionLabel>Recent activity</SectionLabel><QueryMessage isLoading={activity.isLoading} isError={activity.isError} refetch={activity.refetch}>{activity.data?.length ? <div className="divide-y divide-border rounded-lg border border-border bg-card">{activity.data.slice(0, 6).map((item: any) => <div key={item.id} className="flex items-center gap-4 px-4 py-4"><div className="grid h-8 w-8 shrink-0 place-items-center rounded-md bg-muted text-primary">{item.kind === "render" ? <Film size={15} /> : item.kind === "model" ? <Cpu size={15} /> : item.kind === "provider" ? <Server size={15} /> : <Activity size={15} />}</div><div className="min-w-0 flex-1"><p className="truncate text-sm font-medium">{item.title}</p><p className="truncate text-xs text-muted-foreground">{item.detail}</p></div><span className="shrink-0 font-mono text-[10px] text-muted-foreground">{timeAgo(item.createdAt)}</span></div>)}</div> : <EmptyState title="No activity yet" detail="Your production events will appear here as you work." />}</QueryMessage></div>
        </div>
        <div><SectionLabel right={<Link href="/settings" className="text-xs text-primary hover:underline" data-testid="link-open-system-settings">Open settings <ArrowUpRight className="inline" size={13} /></Link>}>System readiness</SectionLabel><QueryMessage isLoading={readiness.isLoading} isError={readiness.isError} refetch={readiness.refetch}>{readiness.data && <div className="rounded-lg border border-border bg-card p-5"><div className="flex items-center gap-3"><div className={`grid h-11 w-11 place-items-center rounded-full border ${readiness.data.status === "ready" ? "border-accent/40 bg-accent/10 text-accent" : "border-amber-300/40 bg-amber-300/10 text-amber-300"}`}><Cpu size={21} /></div><div><p className="font-serif text-lg font-bold">{readiness.data.deviceName}</p><p className="text-xs text-muted-foreground">{readiness.data.chip} · {readiness.data.memory}</p></div></div><div className="mt-6 space-y-3">{readiness.data.checks.slice(0, 4).map((check: any) => <div key={check.name} className="flex items-center gap-3"><span className={`grid h-5 w-5 place-items-center rounded-full ${check.status === "pass" ? "bg-accent/15 text-accent" : "bg-amber-300/15 text-amber-300"}`}>{check.status === "pass" ? <Check size={12} /> : <CircleAlert size={12} />}</span><div className="min-w-0"><p className="text-xs font-medium">{check.name}</p><p className="truncate text-[11px] text-muted-foreground">{check.detail}</p></div></div>)}</div><div className="mt-6 border-t border-border pt-4"><p className="mono-label text-muted-foreground">Local agent</p><div className="mt-2 flex items-center justify-between"><StatusPill status={readiness.data.status} /><span className="font-mono text-[10px] text-muted-foreground">{readiness.data.agent}</span></div></div></div>}</QueryMessage></div>
      </div>
    </div>}</QueryMessage>
  </>;
}

export function ProjectsPage() {
  const { data, isLoading, isError, refetch } = useListProjects(); const create = useCreateProject(); const update = useUpdateProject(); const archive = useDeleteProject(); const queryClient = useQueryClient(); const [, navigate] = useLocation(); const [search, setSearch] = useState(""); const [showCreate, setShowCreate] = useState(false); const [name, setName] = useState(""); const [description, setDescription] = useState(""); const [format, setFormat] = useState("landscape");
  const projects = useMemo(() => (data ?? []).filter((p: any) => `${p.name} ${p.description}`.toLowerCase().includes(search.toLowerCase())), [data, search]);
  const submit = (e: React.FormEvent) => { e.preventDefault(); if (!name.trim()) return; create.mutate({ data: { name, description, format: format as any } }, { onSuccess: (p: any) => { void queryClient.invalidateQueries(); setShowCreate(false); setName(""); setDescription(""); navigate(`/projects/${p.id}`); } }); };
  return <><PageHeader eyebrow="02 / productions" title="Projects" description="Keep every script, scene plan, and delivery preset in one production workspace." action={<Button onClick={() => setShowCreate(true)} data-testid="button-create-project"><Plus size={15} /> New project</Button>} />
    <div className="mb-6 flex flex-col gap-3 md:flex-row"><label className="relative flex-1"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" size={16} /><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search projects by name or description" className="h-11 w-full rounded-md border border-border bg-card pl-10 pr-4 text-sm outline-none transition-colors placeholder:text-muted-foreground/60 focus:border-primary/60" data-testid="input-search-projects" /></label><Button variant="secondary" data-testid="button-project-filters"><SlidersHorizontal size={15} /> Filters</Button></div>
    <QueryMessage isLoading={isLoading} isError={isError} refetch={refetch}>{projects.length ? <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{projects.map((p: any, i: number) => <div key={p.id} className={`studio-in studio-delay-${Math.min(i + 1, 4)} group rounded-lg border border-border bg-card p-5 transition-colors hover:border-primary/40`} data-testid={`card-project-${p.id}`}><div className="flex items-start justify-between"><StatusPill status={p.status} /><button className="rounded p-1 text-muted-foreground hover:bg-muted hover:text-foreground" aria-label={`Project actions for ${p.name}`} data-testid={`button-project-actions-${p.id}`}><MoreHorizontal size={16} /></button></div><Link href={`/projects/${p.id}`} className="mt-5 block" data-testid={`link-project-${p.id}`}><h3 className="font-serif text-xl font-bold tracking-tight group-hover:text-primary">{p.name}</h3><p className="mt-2 line-clamp-2 min-h-10 text-sm leading-relaxed text-muted-foreground">{p.description || "No description added."}</p></Link><div className="mt-6 flex items-center gap-4 border-t border-border pt-4 font-mono text-[10px] text-muted-foreground"><span>{p.scenes} scenes</span><span>{formatDuration(p.durationSeconds)}</span><span className="ml-auto">{timeAgo(p.updatedAt)}</span></div><div className="mt-4 flex gap-2 opacity-0 transition-opacity group-hover:opacity-100"><Button variant="secondary" className="flex-1 py-2" onClick={() => navigate(`/projects/${p.id}`)} data-testid={`button-open-project-${p.id}`}>Open project</Button><Button variant="danger" className="px-3 py-2" onClick={() => archive.mutate({ projectId: p.id }, { onSuccess: () => void queryClient.invalidateQueries() })} data-testid={`button-archive-project-${p.id}`}><Trash2 size={14} /></Button></div></div>)}</div> : <EmptyState title={search ? "No matching projects" : "Your production desk is clear"} detail={search ? "Try another search term." : "Start with a project brief, then shape it into scenes and delivery."} action={!search && <Button onClick={() => setShowCreate(true)} data-testid="button-empty-create-project"><Plus size={15} /> Create first project</Button>} />}</QueryMessage>
    {showCreate && <div className="fixed inset-0 z-50 grid place-items-center bg-background/80 p-5 backdrop-blur-sm"><form onSubmit={submit} className="w-full max-w-lg rounded-lg border border-border bg-card p-6 shadow-2xl" data-testid="form-create-project"><div className="flex items-start justify-between"><div><p className="mono-label text-primary">New production</p><h2 className="mt-2 font-serif text-2xl font-bold">Set the brief.</h2></div><button type="button" onClick={() => setShowCreate(false)} className="text-muted-foreground hover:text-foreground" aria-label="Close create project" data-testid="button-close-create-project"><X size={18} /></button></div><div className="mt-6 space-y-4"><label className="block text-xs font-semibold">Project name<input required value={name} onChange={e => setName(e.target.value)} placeholder="e.g. The quiet workday" className="mt-2 h-11 w-full rounded-md border border-input bg-background px-3 text-sm outline-none focus:border-primary" data-testid="input-project-name" /></label><label className="block text-xs font-semibold">Description<textarea value={description} onChange={e => setDescription(e.target.value)} placeholder="What are you making, and who is it for?" className="mt-2 min-h-24 w-full resize-none rounded-md border border-input bg-background p-3 text-sm outline-none focus:border-primary" data-testid="input-project-description" /></label><label className="block text-xs font-semibold">Frame format<select value={format} onChange={e => setFormat(e.target.value)} className="mt-2 h-11 w-full rounded-md border border-input bg-background px-3 text-sm outline-none focus:border-primary" data-testid="select-project-format"><option value="landscape">Landscape · 16:9</option><option value="portrait">Portrait · 9:16</option><option value="square">Square · 1:1</option></select></label></div><div className="mt-6 flex justify-end gap-2"><Button type="button" variant="ghost" onClick={() => setShowCreate(false)} data-testid="button-cancel-create-project">Cancel</Button><Button type="submit" disabled={create.isPending} data-testid="button-submit-create-project">{create.isPending ? "Creating…" : "Create project"}</Button></div></form></div>}
  </>;
}

export function ProjectDetailPage() {
  const params = useParams<{ id: string }>(); const id = Number(params.id); const project = useGetProject(id); const savedPlan = useGetProjectPlan(id); const createPlan = useCreateProjectPlan(); const update = useUpdateProject(); const queryClient = useQueryClient(); const [script, setScript] = useState(""); const [tone, setTone] = useState("documentary"); const [language, setLanguage] = useState("en"); const [plan, setPlan] = useState<any>(null); const [tab, setTab] = useState("script");
  useEffect(() => { if (savedPlan.data) { setPlan(savedPlan.data); setTab((current) => current === "script" ? "scenes" : current); } }, [savedPlan.data]);
  if (project.isLoading) return <LoadingState />; if (project.isError || !project.data) return <ErrorState retry={project.refetch} />;
  const p: any = project.data; const submitPlan = () => { if (!script.trim()) return; createPlan.mutate({ projectId: id, data: { script, tone: tone as any, language: language as any } }, { onSuccess: (result: any) => { void queryClient.invalidateQueries(); setPlan(result); setTab("scenes"); update.mutate({ projectId: id, data: { status: "planning" } }); } }); };
  return <><BackLink href="/projects">All projects</BackLink><PageHeader eyebrow={`Project ${String(id).padStart(3, "0")} / ${p.status}`} title={p.name} description={p.description} action={<div className="flex gap-2"><Button variant="secondary" onClick={() => update.mutate({ projectId: id, data: { status: p.status === "archived" ? "draft" : "archived" } })} data-testid="button-toggle-project-archive">{p.status === "archived" ? "Restore" : "Archive"}</Button><Link href="/render" className="inline-flex items-center gap-2 rounded-md bg-primary px-4 py-2.5 text-xs font-semibold text-primary-foreground" data-testid="link-project-render"><Film size={15} /> Render</Link></div>} />
    <div className="mb-6 flex gap-1 border-b border-border"><button onClick={() => setTab("script")} className={`border-b-2 px-4 py-3 text-xs font-semibold ${tab === "script" ? "border-primary text-foreground" : "border-transparent text-muted-foreground"}`} data-testid="button-tab-script">Script plan</button><button onClick={() => setTab("scenes")} className={`border-b-2 px-4 py-3 text-xs font-semibold ${tab === "scenes" ? "border-primary text-foreground" : "border-transparent text-muted-foreground"}`} data-testid="button-tab-scenes">Scenes {plan?.scenes?.length ? `(${plan.scenes.length})` : ""}</button></div>
    {tab === "script" ? <div className="grid gap-6 xl:grid-cols-[1fr_340px]"><div className="rounded-lg border border-border bg-card p-5"><div className="mb-4 flex items-center justify-between"><div><p className="mono-label text-primary">Script input</p><h2 className="mt-1 font-serif text-xl font-bold">Shape the narrative</h2></div><span className="font-mono text-[10px] text-muted-foreground">{script.length} chars</span></div><textarea value={script} onChange={e => setScript(e.target.value)} placeholder="Paste or write the narration for this production. The planner will divide it into deliverable scenes with narration and visual direction." className="min-h-[390px] w-full resize-y rounded-md border border-input bg-background p-4 text-sm leading-7 outline-none focus:border-primary" data-testid="textarea-project-script" /></div><div className="space-y-4"><div className="rounded-lg border border-border bg-card p-5"><p className="mono-label text-muted-foreground">Plan controls</p><label className="mt-5 block text-xs font-semibold">Language<select value={language} onChange={e => setLanguage(e.target.value)} className="mt-2 h-10 w-full rounded-md border border-input bg-background px-3 text-sm" data-testid="select-plan-language"><option value="en">English</option><option value="bn">Bangla</option><option value="mixed">Mixed</option></select></label><label className="mt-4 block text-xs font-semibold">Tone<select value={tone} onChange={e => setTone(e.target.value)} className="mt-2 h-10 w-full rounded-md border border-input bg-background px-3 text-sm" data-testid="select-plan-tone"><option value="documentary">Documentary</option><option value="cinematic">Cinematic</option><option value="educational">Educational</option><option value="commercial">Commercial</option><option value="social">Social</option></select></label><Button onClick={submitPlan} disabled={createPlan.isPending || !script.trim()} className="mt-6 w-full" data-testid="button-generate-plan"><WandSparkles size={15} />{createPlan.isPending ? "Planning scenes…" : "Build scene plan"}</Button></div><div className="rounded-lg border border-accent/25 bg-accent/5 p-5"><div className="flex gap-3"><LockKeyhole size={16} className="mt-0.5 shrink-0 text-accent" /><div><p className="text-xs font-semibold">Local-first by default</p><p className="mt-1 text-xs leading-relaxed text-muted-foreground">Your script stays on this device unless you explicitly route a task to a configured provider.</p></div></div></div></div></div> : <ScenePlanView plan={plan} onSaved={(result) => { setPlan(result); void queryClient.invalidateQueries(); }} />}
  </>;
}

function ScenePlanView({ plan, onSaved }: { plan: any; onSaved: (plan: any) => void }) {
  const update = useUpdateProjectPlan();
  const assets = useListStudioAssets();
  const [scenes, setScenes] = useState<any[]>([]);
  useEffect(() => { setScenes(plan?.scenes ?? []); }, [plan]);
  if (!plan) return <EmptyState title="No scene plan yet" detail="Add a script and build a plan to see narration, visuals, timing, and asset status." />;
  const voiceProfiles = (assets.data ?? []).filter((asset: any) => asset.kind === "voice-profile");
  const presenterReferences = (assets.data ?? []).filter((asset: any) => asset.kind === "presenter-reference");
  const updateScene = (index: number, patch: Record<string, unknown>) => {
    setScenes((current) => current.map((scene) => scene.index === index ? { ...scene, ...patch } : scene));
  };
  const updateDelivery = (index: number, patch: Record<string, unknown>) => {
    setScenes((current) => current.map((scene) => scene.index === index ? { ...scene, delivery: { ...scene.delivery, ...patch } } : scene));
  };
  const save = () => {
    update.mutate({ projectId: plan.projectId, data: { scenes } }, { onSuccess: onSaved });
  };
  return <div className="space-y-4">
    <div className="flex flex-col justify-between gap-3 rounded-lg border border-accent/25 bg-accent/5 p-4 sm:flex-row sm:items-center">
      <div><p className="text-sm font-semibold">Tune the delivery scene by scene</p><p className="mt-1 text-xs text-muted-foreground">Timing and delivery settings are saved with this plan and used by preview and final renders.</p></div>
      <Button onClick={save} disabled={update.isPending || !scenes.length} data-testid="button-save-scene-settings"><Check size={15} /> {update.isPending ? "Saving…" : "Save scene settings"}</Button>
    </div>
    {update.isError && <p className="rounded-md bg-destructive/10 px-3 py-2 text-xs text-red-200">Unable to save scene settings. Check the timing and selected assets, then try again.</p>}
    {scenes.map((scene) => <div key={scene.index} className="rounded-lg border border-border bg-card p-5" data-testid={`card-scene-${scene.index}`}>
      <div className="flex items-start gap-4"><span className="font-mono text-xs text-primary">0{scene.index}</span><div className="min-w-0 flex-1">
        <div className="flex flex-col justify-between gap-2 md:flex-row"><h3 className="font-serif text-lg font-bold">{scene.title}</h3><StatusPill status={scene.assetStatus} /></div>
        <p className="mt-3 text-sm leading-relaxed text-foreground/80">{scene.narration}</p>
        <div className="mt-4 rounded-md bg-muted/60 p-3"><p className="mono-label text-muted-foreground">Visual direction</p><p className="mt-1 text-xs text-muted-foreground">{scene.visualPrompt}</p></div>
        <div className="mt-5 grid gap-4 sm:grid-cols-3">
          <label className="text-xs font-semibold">Scene duration (seconds)<input type="number" min="1" max="120" step="0.1" value={scene.durationSeconds} onChange={(event) => { const durationSeconds = Math.max(1, Math.min(120, Number(event.target.value) || 1)); updateScene(scene.index, { durationSeconds, subtitleStartSeconds: Math.min(scene.subtitleStartSeconds, Math.max(0, durationSeconds - 0.1)), subtitleEndSeconds: Math.min(scene.subtitleEndSeconds, durationSeconds) }); }} className="mt-2 h-10 w-full rounded-md border border-input bg-background px-3 text-sm" data-testid={`input-scene-duration-${scene.index}`} /></label>
          <label className="text-xs font-semibold">Subtitle in (seconds)<input type="number" min="0" max={scene.durationSeconds} step="0.1" value={scene.subtitleStartSeconds} onChange={(event) => updateScene(scene.index, { subtitleStartSeconds: Math.max(0, Math.min(scene.durationSeconds - 0.1, Number(event.target.value) || 0)) })} className="mt-2 h-10 w-full rounded-md border border-input bg-background px-3 text-sm" data-testid={`input-scene-subtitle-start-${scene.index}`} /></label>
          <label className="text-xs font-semibold">Subtitle out (seconds)<input type="number" min="0.1" max={scene.durationSeconds} step="0.1" value={scene.subtitleEndSeconds} onChange={(event) => updateScene(scene.index, { subtitleEndSeconds: Math.max(scene.subtitleStartSeconds + 0.1, Math.min(scene.durationSeconds, Number(event.target.value) || scene.durationSeconds)) })} className="mt-2 h-10 w-full rounded-md border border-input bg-background px-3 text-sm" data-testid={`input-scene-subtitle-end-${scene.index}`} /></label>
        </div>
        <div className="mt-4 rounded-md border border-border p-4">
          <div className="flex items-center justify-between"><p className="mono-label text-muted-foreground">Voice delivery</p><span className="font-mono text-[10px] text-muted-foreground">{scene.delivery.rate.toFixed(2)}× speed</span></div>
          <div className="mt-3 grid gap-4 sm:grid-cols-2">
            <label className="text-xs font-semibold">Voice profile<select value={scene.delivery.voiceProfileId ?? ""} onChange={(event) => updateDelivery(scene.index, { voiceProfileId: event.target.value ? Number(event.target.value) : null })} className="mt-2 h-10 w-full rounded-md border border-input bg-background px-3 text-sm" data-testid={`select-scene-voice-${scene.index}`}><option value="">Default local voice</option>{voiceProfiles.map((asset: any) => <option key={asset.id} value={asset.id}>{asset.name}</option>)}</select></label>
            <label className="text-xs font-semibold">Rate<input type="range" min="0.5" max="2" step="0.05" value={scene.delivery.rate} onChange={(event) => updateDelivery(scene.index, { rate: Number(event.target.value) })} className="mt-3 w-full accent-[hsl(var(--primary))]" data-testid={`input-scene-rate-${scene.index}`} /></label>
            <label className="text-xs font-semibold">Pitch<input type="number" min="-8" max="8" step="0.5" value={scene.delivery.pitch} onChange={(event) => updateDelivery(scene.index, { pitch: Math.max(-8, Math.min(8, Number(event.target.value) || 0)) })} className="mt-2 h-10 w-full rounded-md border border-input bg-background px-3 text-sm" data-testid={`input-scene-pitch-${scene.index}`} /></label>
            <label className="text-xs font-semibold">Pause after punctuation (ms)<input type="number" min="0" max="1000" step="10" value={scene.delivery.pauseMs} onChange={(event) => updateDelivery(scene.index, { pauseMs: Math.max(0, Math.min(1000, Number(event.target.value) || 0)) })} className="mt-2 h-10 w-full rounded-md border border-input bg-background px-3 text-sm" data-testid={`input-scene-pause-${scene.index}`} /></label>
            <label className="text-xs font-semibold sm:col-span-2">Pronunciation notes<input value={scene.delivery.pronunciation ?? ""} onChange={(event) => updateDelivery(scene.index, { pronunciation: event.target.value || null })} placeholder="Optional words or names to read precisely" className="mt-2 h-10 w-full rounded-md border border-input bg-background px-3 text-sm" data-testid={`input-scene-pronunciation-${scene.index}`} /></label>
          </div>
        </div>
        <div className="mt-4 rounded-md border border-border p-4">
          <p className="mono-label text-muted-foreground">Presenter delivery</p>
          <div className="mt-3 grid gap-4 sm:grid-cols-2">
            <label className="text-xs font-semibold">Mode<select value={scene.delivery.presenterMode} onChange={(event) => updateDelivery(scene.index, { presenterMode: event.target.value })} className="mt-2 h-10 w-full rounded-md border border-input bg-background px-3 text-sm" data-testid={`select-scene-presenter-mode-${scene.index}`}><option value="none">Narration only</option><option value="lipsync">Lip-sync</option><option value="scene">Scene presenter</option></select></label>
            <label className="text-xs font-semibold">Presenter reference<select value={scene.delivery.presenterAssetId ?? ""} onChange={(event) => updateDelivery(scene.index, { presenterAssetId: event.target.value ? Number(event.target.value) : null })} className="mt-2 h-10 w-full rounded-md border border-input bg-background px-3 text-sm" data-testid={`select-scene-presenter-${scene.index}`}><option value="">No reference selected</option>{presenterReferences.map((asset: any) => <option key={asset.id} value={asset.id}>{asset.name}</option>)}</select></label>
             <label className="text-xs font-semibold">Framing<select value={scene.delivery.presenterFraming} onChange={(event) => updateDelivery(scene.index, { presenterFraming: event.target.value })} className="mt-2 h-10 w-full rounded-md border border-input bg-background px-3 text-sm" data-testid={`select-scene-presenter-framing-${scene.index}`}><option value="close-up">Close-up</option><option value="waist-up">Waist-up</option><option value="full-body">Full body</option></select></label>
             <label className="text-xs font-semibold">Delivery mode<select value={scene.delivery.presenterDeliveryMode} onChange={(event) => updateDelivery(scene.index, { presenterDeliveryMode: event.target.value })} className="mt-2 h-10 w-full rounded-md border border-input bg-background px-3 text-sm" data-testid={`select-scene-presenter-delivery-${scene.index}`}><option value="conversational">Conversational</option><option value="presentational">Presentational</option><option value="energetic">Energetic</option><option value="calm">Calm</option></select></label>
          </div>
        </div>
        <label className="mt-4 flex items-center gap-3 text-xs font-semibold"><input type="checkbox" checked={scene.delivery.subtitlesEnabled} onChange={(event) => updateDelivery(scene.index, { subtitlesEnabled: event.target.checked })} className="h-4 w-4 accent-[hsl(var(--primary))]" data-testid={`checkbox-scene-subtitles-${scene.index}`} /> Burn subtitles for this scene</label>
        <p className="mt-3 font-mono text-[10px] text-muted-foreground">Timeline position · {formatDuration(scene.durationSeconds)} · subtitle {scene.subtitleStartSeconds.toFixed(1)}s–{scene.subtitleEndSeconds.toFixed(1)}s</p>
      </div></div>
    </div>)}
  </div>;
}

const activeInstallStatuses = ["approved", "queued", "downloading", "installing"];

function installStatusLabel(status: string) {
  if (status === "pending-approval") return "Approval needed";
  if (status === "downloading") return "Downloading model";
  if (status === "installing") return "Installing locally";
  if (status === "complete") return "Installed on Mac";
  if (status === "failed") return "Install stopped";
  return status;
}

function formatExpiry(expiresAt?: string) {
  if (!expiresAt) return "expires soon";
  const minutes = Math.max(0, Math.ceil((new Date(expiresAt).getTime() - Date.now()) / 60000));
  return minutes > 0 ? `expires in ${minutes} min` : "expired";
}

function BridgeAvailability({ readiness, isLoading, isError }: { readiness: any; isLoading: boolean; isError: boolean }) {
  if (isLoading) return <div className="mb-6 h-14 animate-pulse rounded-lg border border-border bg-card" aria-label="Checking Mac bridge status" />;
  if (isError || !readiness) return <div className="mb-6 flex items-start gap-3 rounded-lg border border-destructive/25 bg-destructive/10 p-4" data-testid="status-models-bridge-offline"><WifiOff size={17} className="mt-0.5 shrink-0 text-red-200" /><div><p className="text-xs font-semibold text-red-100">Mac bridge status unavailable</p><p className="mt-1 text-xs text-red-100/70">Model installs are paused until the local worker responds. Open Settings to reconnect it.</p></div><Link href="/settings" className="ml-auto shrink-0 text-xs font-semibold text-red-100 underline" data-testid="link-models-open-settings">Open settings</Link></div>;
  if (!readiness.bridgeConnected) return <div className="mb-6 flex items-start gap-3 rounded-lg border border-amber-300/25 bg-amber-300/[.07] p-4" data-testid="status-models-bridge-disconnected"><CircleAlert size={17} className="mt-0.5 shrink-0 text-amber-300" /><div><p className="text-xs font-semibold text-amber-100">Connect the Mac worker before installing</p><p className="mt-1 text-xs text-amber-100/70">The model request will be sent to this signed worker and approved separately.</p></div><Link href="/settings" className="ml-auto shrink-0 text-xs font-semibold text-amber-200 underline" data-testid="link-models-pair-settings">Pair in settings</Link></div>;
  return <div className="mb-6 flex items-center gap-3 rounded-lg border border-accent/20 bg-accent/[.06] px-4 py-3" data-testid="status-models-bridge-connected"><span className="h-2 w-2 rounded-full bg-accent" /><p className="text-xs text-accent"><span className="font-semibold">{readiness.deviceName}</span> connected · {readiness.workerVersion ? `worker ${readiness.workerVersion}` : "signed worker"} · installs stay on this Mac</p><ShieldCheck size={16} className="ml-auto text-accent" /></div>;
}

function InstallLifecycle({ job, queryLoading, queryError, onRetryFetch }: { job: any; queryLoading: boolean; queryError: boolean; onRetryFetch: () => void }) {
  if (queryLoading && !job) return <div className="rounded-lg border border-border bg-card p-5" aria-label="Loading install job"><div className="h-4 w-36 animate-pulse rounded bg-muted" /><div className="mt-5 h-2 animate-pulse rounded bg-muted" /><div className="mt-4 h-20 animate-pulse rounded bg-muted/70" /></div>;
  if (queryError && !job) return <div className="rounded-lg border border-destructive/25 bg-destructive/10 p-5" data-testid="status-install-job-error"><p className="text-sm font-semibold text-red-100">Install details are temporarily unavailable</p><p className="mt-1 text-xs text-red-100/70">The model may still be working on the Mac.</p><Button variant="danger" className="mt-4" onClick={onRetryFetch} data-testid="button-retry-install-details"><RefreshCw size={14} /> Check again</Button></div>;
  if (!job) return null;
  const terminal = job.status === "complete" || job.status === "failed";
  return <div className="rounded-lg border border-border bg-card p-5 studio-in" data-testid={`card-install-job-${job.id}`}>
    <div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-start"><div><p className="mono-label text-primary">Install lifecycle</p><h2 className="mt-2 font-serif text-xl font-bold">{job.modelName}</h2><p className="mt-1 text-xs text-muted-foreground">{installStatusLabel(job.status)} · job {job.id}</p></div><StatusPill status={job.status} /></div>
    <div className="mt-5"><div className="flex justify-between font-mono text-[10px] text-muted-foreground"><span>{job.progress}% complete</span><span>{terminal ? "worker reported final state" : "watching signed Mac worker"}</span></div><div className="mt-2 h-2 overflow-hidden rounded-full bg-muted"><div className={`h-full rounded-full transition-all duration-500 ${job.status === "failed" ? "bg-amber-300" : "bg-primary"}`} style={{ width: `${Math.min(100, Math.max(0, job.progress))}%` }} /></div></div>
    {job.error && <div className="mt-4 rounded-md border border-amber-300/20 bg-amber-300/[.07] p-3 text-xs text-amber-100" data-testid="text-install-job-error">{job.error}</div>}
    <div className="mt-5 rounded-md border border-border bg-background/70 p-3"><div className="flex items-center justify-between"><span className="mono-label text-muted-foreground">Worker log</span><span className="font-mono text-[10px] text-muted-foreground">{job.logs?.length ?? 0} events</span></div><div className="mt-3 max-h-32 space-y-1 overflow-auto font-mono text-[10px] leading-relaxed text-muted-foreground">{job.logs?.length ? job.logs.slice(-8).map((log: string, index: number) => <p key={`${job.id}-log-${index}`} data-testid={`text-install-log-${index}`}><span className="mr-2 text-primary">›</span>{log}</p>) : <p>No worker events yet. The Mac will report progress here.</p>}</div></div>
  </div>;
}

export function ModelsPage() {
  const modelsQuery = useListModels();
  const readiness = useGetSystemReadiness();
  const install = useInstallModel();
  const approve = useApproveModelInstall();
  const retry = useRetryModelInstall();
  const queryClient = useQueryClient();
  const [filter, setFilter] = useState("all");
  const [activeModelId, setActiveModelId] = useState<number | null>(null);
  const [activeJob, setActiveJob] = useState<any>(null);
  const modelList = useMemo(() => modelsQuery.data ?? [], [modelsQuery.data]);
  const models = useMemo(() => modelList.filter((m: any) => filter === "all" || m.status === filter), [modelList, filter]);
  const activeModel = useMemo(() => modelList.find((model: any) => model.id === activeModelId), [modelList, activeModelId]);
  const jobQuery = useGetModelInstall(activeModelId ?? 0, { query: { enabled: activeModelId !== null, queryKey: getGetModelInstallQueryKey(activeModelId ?? 0), refetchInterval: activeJob && activeInstallStatuses.includes(activeJob.status) ? 2500 : false } });
  const fetchedJob = useMemo(() => jobQuery.data ?? null, [jobQuery.data]);
  const currentJob = fetchedJob ?? activeJob;

  useEffect(() => {
    if (activeModelId === null) {
      const installingModel = modelList.find((model: any) => model.status === "installing");
      if (installingModel) setActiveModelId(installingModel.id);
    }
  }, [modelList, activeModelId]);

  useEffect(() => {
    if (!fetchedJob) return;
    setActiveJob(fetchedJob);
    if (fetchedJob.status === "complete" || fetchedJob.status === "failed") void queryClient.invalidateQueries({ queryKey: getListModelsQueryKey() });
  }, [fetchedJob, queryClient]);

  const invalidateModelState = (modelId: number) => {
    void queryClient.invalidateQueries({ queryKey: getListModelsQueryKey() });
    void queryClient.invalidateQueries({ queryKey: getGetModelInstallQueryKey(modelId) });
  };
  const requestInstall = (modelId: number) => {
    setActiveModelId(modelId);
    install.mutate({ modelId }, { onSuccess: (job: any) => { setActiveJob(job); invalidateModelState(modelId); } });
  };
  const approveInstall = (modelId: number) => approve.mutate({ modelId }, { onSuccess: (job: any) => { setActiveJob(job); invalidateModelState(modelId); } });
  const retryInstall = (modelId: number) => retry.mutate({ modelId }, { onSuccess: (job: any) => { setActiveJob(job); invalidateModelState(modelId); } });
  const bridgeReady = Boolean(readiness.data?.bridgeConnected);
  const actionPending = install.isPending || approve.isPending || retry.isPending;

  return <><PageHeader eyebrow="03 / model center" title="Models" description="Know exactly what is installed, what is ready to pull, and what each runtime can do." action={<div className="flex items-center gap-2 rounded-md border border-accent/20 bg-accent/5 px-3 py-2 text-xs text-accent"><HardDrive size={14} /> Local storage active</div>} />
    <BridgeAvailability readiness={readiness.data} isLoading={readiness.isLoading} isError={readiness.isError} />
    {activeModelId !== null && <div className="mb-7"><InstallLifecycle job={currentJob} queryLoading={jobQuery.isLoading} queryError={jobQuery.isError} onRetryFetch={jobQuery.refetch} /></div>}
    {(install.isError || approve.isError || retry.isError) && <div className="mb-6 flex items-start gap-3 rounded-lg border border-destructive/25 bg-destructive/10 p-4" data-testid="status-model-install-error"><CircleAlert size={17} className="mt-0.5 shrink-0 text-red-200" /><div className="min-w-0 flex-1"><p className="text-xs font-semibold text-red-100">The install action could not be completed</p><p className="mt-1 text-xs text-red-100/70">{String(((install.error || approve.error || retry.error) as any)?.message ?? "The local service returned an error. No model files were changed.")}</p></div>{activeModelId !== null && <Button variant="danger" onClick={() => currentJob?.status === "failed" ? retryInstall(activeModelId) : requestInstall(activeModelId)} data-testid="button-recover-model-install"><RefreshCw size={14} /> Try again</Button>}</div>}
    <div className="mb-6 flex gap-2 overflow-auto">{["all", "installed", "available", "installing", "attention"].map(item => <button key={item} onClick={() => setFilter(item)} className={`whitespace-nowrap rounded-sm border px-3 py-2 text-xs font-semibold capitalize ${filter === item ? "border-primary/40 bg-primary/10 text-primary" : "border-border text-muted-foreground hover:text-foreground"}`} data-testid={`button-filter-models-${item}`}>{item}</button>)}</div>
    <QueryMessage isLoading={modelsQuery.isLoading} isError={modelsQuery.isError} refetch={modelsQuery.refetch}>{models.length ? <div className="grid gap-3 lg:grid-cols-2">{models.map((m: any, index: number) => {
      const modelJob = currentJob?.modelId === m.id ? currentJob : null;
      const canInstall = bridgeReady && !actionPending;
      return <div key={m.id} className={`studio-in studio-delay-${Math.min(index + 1, 4)} rounded-lg border bg-card p-5 ${activeModelId === m.id ? "border-primary/45" : "border-border"}`} data-testid={`card-model-${m.id}`}>
        <div className="flex items-start justify-between gap-3"><div><div className="flex items-center gap-2"><h3 className="font-serif text-lg font-bold">{m.name}</h3>{m.recommended && <span className="rounded-sm bg-primary/10 px-2 py-1 text-[9px] font-bold uppercase tracking-wider text-primary">Recommended</span>}</div><p className="mt-1 text-xs text-muted-foreground">{m.provider} · {m.runtime}</p>{m.name.toLowerCase().includes("phi-3") && <p className="mt-2 text-[11px] text-accent">Safe setup: request, review, then approve the local install.</p>}</div><StatusPill status={modelJob?.status ?? m.status} /></div>
        <div className="mt-5 grid grid-cols-2 gap-3 border-y border-border py-4"><div><p className="mono-label text-muted-foreground">Purpose</p><p className="mt-1 text-xs">{m.purpose}</p></div><div><p className="mono-label text-muted-foreground">Footprint</p><p className="mt-1 font-mono text-xs">{m.size}</p></div></div>
        {modelJob?.status === "pending-approval" && <div className="mt-4 rounded-md border border-primary/25 bg-primary/[.06] p-3"><p className="text-xs font-semibold">Ready for your approval</p><p className="mt-1 text-[11px] leading-relaxed text-muted-foreground">The Mac worker has not downloaded anything. Approve only if this is the model you intended to install.</p></div>}
        {modelJob?.status === "failed" && <div className="mt-4 rounded-md border border-amber-300/20 bg-amber-300/[.06] p-3 text-xs text-amber-100">{modelJob.error ?? "The worker could not complete this install."}</div>}
        <div className="mt-4 flex flex-wrap items-center justify-between gap-2"><span className="font-mono text-[10px] text-muted-foreground">{modelJob ? `${modelJob.progress}% · ${timeAgo(modelJob.updatedAt)}` : m.status === "installed" ? "Available offline" : "Not on this Mac"}</span>{modelJob?.status === "pending-approval" ? <Button onClick={() => approveInstall(m.id)} disabled={!canInstall} data-testid={`button-approve-model-${m.id}`}><ShieldCheck size={14} /> {approve.isPending ? "Approving…" : "Approve install"}</Button> : modelJob?.status === "failed" && modelJob.canRetry ? <Button variant="secondary" onClick={() => retryInstall(m.id)} disabled={!canInstall} data-testid={`button-retry-model-${m.id}`}><RefreshCw size={14} /> {retry.isPending ? "Retrying…" : "Retry install"}</Button> : m.status === "available" || m.status === "attention" ? <Button onClick={() => requestInstall(m.id)} disabled={!canInstall} title={!bridgeReady ? "Pair the Mac worker in Settings first" : undefined} data-testid={`button-install-model-${m.id}`}><Download size={14} /> {install.isPending && activeModelId === m.id ? "Requesting…" : "Request install"}</Button> : m.status === "installing" ? <Button variant="secondary" onClick={() => { setActiveModelId(m.id); setActiveJob(null); }} data-testid={`button-show-install-${m.id}`}><RefreshCw size={14} /> View progress</Button> : <span className="inline-flex items-center gap-2 text-xs font-semibold text-accent"><Check size={14} /> Ready locally</span>}</div>
      </div>;
    })}</div> : <EmptyState title="No models match this view" detail="Adjust the filter or refresh the model center." />}</QueryMessage>
    {activeModel && currentJob && <p className="mt-5 text-[11px] text-muted-foreground">Showing live worker events for <span className="font-semibold text-foreground">{activeModel.name}</span>. Approval and retries are separate actions by design.</p>}
  </>;
}

export function VoicePage() {
  const { data: providers, isLoading, isError, refetch } = useListProviders(); const [active, setActive] = useState("profiles"); const [selected, setSelected] = useState("Maya / Neutral"); const voices = [{ name: "Maya / Neutral", detail: "Warm, measured · English (US)", tag: "Production" }, { name: "Arun / Editorial", detail: "Low register · English (IN)", tag: "Review" }, { name: "Aster / Narration", detail: "Clear, close-mic · Synthetic", tag: "Local" }];
  return <><PageHeader eyebrow="04 / voice workspace" title="Voice" description="Build a repeatable vocal chain. Profiles, pronunciation, and routing stay explicit." action={<Button onClick={() => setSelected("New voice profile")} data-testid="button-new-voice-profile"><Plus size={15} /> New profile</Button>} /><div className="mb-6 flex gap-1 border-b border-border"><button onClick={() => setActive("profiles")} className={`border-b-2 px-4 py-3 text-xs font-semibold ${active === "profiles" ? "border-primary text-foreground" : "border-transparent text-muted-foreground"}`} data-testid="button-tab-voice-profiles">Voice profiles</button><button onClick={() => setActive("routing")} className={`border-b-2 px-4 py-3 text-xs font-semibold ${active === "routing" ? "border-primary text-foreground" : "border-transparent text-muted-foreground"}`} data-testid="button-tab-voice-routing">Provider routing</button></div>{active === "profiles" ? <div className="grid gap-6 xl:grid-cols-[.85fr_1.15fr]"><div className="space-y-2">{voices.map((voice, i) => <button key={voice.name} onClick={() => setSelected(voice.name)} className={`w-full rounded-lg border p-4 text-left transition-colors ${selected === voice.name ? "border-primary/50 bg-primary/[.07]" : "border-border bg-card hover:border-primary/30"}`} data-testid={`button-voice-profile-${i}`}><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-full border border-accent/30 bg-accent/10 text-accent"><UserRound size={17} /></div><div className="min-w-0 flex-1"><p className="text-sm font-semibold">{voice.name}</p><p className="mt-1 text-xs text-muted-foreground">{voice.detail}</p></div><span className="mono-label text-muted-foreground">{voice.tag}</span></div></button>)}</div><div className="rounded-lg border border-border bg-card p-5"><div className="flex items-start justify-between"><div><p className="mono-label text-primary">Active voice profile</p><h2 className="mt-2 font-serif text-2xl font-bold">{selected}</h2></div><Button variant="secondary" disabled title="Voice profiles will be persisted by the local worker" data-testid="button-save-voice-profile">Save profile</Button></div><div className="mt-7 rounded-lg border border-border bg-background p-4"><div className="flex items-center justify-between"><span className="mono-label text-muted-foreground">Preview phrase</span><button className="grid h-9 w-9 place-items-center rounded-full bg-primary text-primary-foreground" aria-label="Play voice preview" data-testid="button-play-voice-preview"><Play size={15} fill="currentColor" /></button></div><p className="mt-4 text-sm leading-7 text-foreground/80">A clear idea, delivered at the right pace, gives the audience somewhere to look.</p><div className="mt-5 flex h-10 items-center gap-1 overflow-hidden">{Array.from({ length: 52 }).map((_, i) => <span key={i} className="w-1 rounded-full bg-primary/60" style={{ height: `${12 + ((i * 17) % 25)}px` }} />)}</div></div><div className="mt-6 grid gap-4 sm:grid-cols-2"><label className="text-xs font-semibold">Pace<input type="range" min="0" max="100" defaultValue="48" className="mt-3 w-full accent-[hsl(var(--primary))]" data-testid="input-voice-pace" /></label><label className="text-xs font-semibold">Presence<input type="range" min="0" max="100" defaultValue="72" className="mt-3 w-full accent-[hsl(var(--primary))]" data-testid="input-voice-presence" /></label></div><div className="mt-6 rounded-md border border-border p-4"><div className="flex items-center gap-2"><AudioWaveform size={15} className="text-accent" /><p className="text-xs font-semibold">Pronunciation dictionary</p><span className="ml-auto font-mono text-[10px] text-muted-foreground">12 entries</span></div><p className="mt-2 text-xs text-muted-foreground">Add terms that need a precise read before voice synthesis.</p><Button variant="ghost" className="mt-3 px-0" disabled data-testid="button-edit-pronunciation">Edit dictionary <ArrowUpRight size={13} /></Button></div></div></div> : <ProviderPanel providers={providers} isLoading={isLoading} isError={isError} refetch={refetch} />}
  </>;
}

function ProviderPanel({ providers, isLoading, isError, refetch, update }: any) { return <QueryMessage isLoading={isLoading} isError={isError} refetch={refetch}><div className="grid gap-3 md:grid-cols-2">{(providers ?? []).map((provider: any) => <div key={provider.id} className="rounded-lg border border-border bg-card p-5" data-testid={`card-provider-${provider.id}`}><div className="flex items-start justify-between"><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-md bg-muted text-accent"><Server size={17} /></div><div><h3 className="text-sm font-semibold">{provider.name}</h3><p className="mt-1 text-xs capitalize text-muted-foreground">{provider.kind.replaceAll("-", " ")}</p></div></div><StatusPill status={provider.status} /></div><p className="mt-5 text-xs leading-relaxed text-muted-foreground">{provider.detail}</p><div className="mt-5 flex items-center justify-between border-t border-border pt-4"><span className="font-mono text-[10px] text-muted-foreground">{provider.tokenConfigured ? "Token configured · masked" : "No token configured"}</span>{provider.kind === "huggingface" && <Button variant="secondary" disabled title="Connect the local desktop bridge to store this credential securely" data-testid={`button-configure-provider-${provider.id}`}>Requires desktop bridge</Button>}</div></div>)}</div></QueryMessage>; }

export function AvatarPage() { const [mode, setMode] = useState("portrait"); const [selected, setSelected] = useState("Jordan / Executive"); const presenters = ["Jordan / Executive", "Nia / Technical", "Elliot / Editorial"]; return <><PageHeader eyebrow="05 / human presenter" title="Avatar delivery" description="Prepare realistic human presentation with controlled portrait, lip-sync, and scene delivery." action={<Button data-testid="button-new-presenter"><Plus size={15} /> Add presenter</Button>} /><div className="grid gap-6 xl:grid-cols-[.75fr_1.25fr]"><div className="rounded-lg border border-border bg-card p-5"><div className="flex items-center justify-between"><p className="mono-label text-muted-foreground">Presenter library</p><button className="text-muted-foreground hover:text-foreground" aria-label="Presenter library options" data-testid="button-presenter-options"><MoreHorizontal size={16} /></button></div><div className="mt-5 space-y-2">{presenters.map(name => <button key={name} onClick={() => setSelected(name)} className={`flex w-full items-center gap-3 rounded-md border p-3 text-left ${selected === name ? "border-primary/50 bg-primary/[.07]" : "border-border hover:border-primary/30"}`} data-testid={`button-presenter-${name.split(" ")[0].toLowerCase()}`}><div className="grid h-11 w-11 place-items-center rounded-full border border-border bg-muted text-muted-foreground"><UserRound size={18} /></div><div><p className="text-sm font-semibold">{name}</p><p className="mt-1 text-xs text-muted-foreground">Portrait capture available</p></div>{selected === name && <Check size={15} className="ml-auto text-primary" />}</button>)}</div><div className="mt-6 rounded-md border border-accent/20 bg-accent/5 p-4"><p className="text-xs font-semibold text-accent">Capture guidance</p><p className="mt-2 text-xs leading-relaxed text-muted-foreground">Use even front light, neutral framing, and a clean 5–8 second reference clip for consistent delivery.</p></div></div><div className="rounded-lg border border-border bg-card p-5"><div className="flex flex-wrap gap-2 border-b border-border pb-4">{["portrait", "lip-sync", "scene delivery"].map(item => <button key={item} onClick={() => setMode(item)} className={`rounded-sm px-3 py-2 text-xs font-semibold capitalize ${mode === item ? "bg-primary text-primary-foreground" : "bg-muted text-muted-foreground"}`} data-testid={`button-avatar-mode-${item.replace(" ", "-")}`}>{item}</button>)}</div><div className="mt-6 grid min-h-[390px] place-items-center rounded-md border border-dashed border-border bg-background/80"><div className="text-center"><div className="mx-auto grid h-20 w-20 place-items-center rounded-full border border-primary/30 bg-primary/10 text-primary"><UserRound size={32} /></div><p className="mt-5 font-serif text-xl font-bold">{selected}</p><p className="mt-2 max-w-sm text-sm text-muted-foreground">{mode === "portrait" ? "Portrait framing and expression controls are ready." : mode === "lip-sync" ? "Upload narration to inspect mouth timing and phoneme alignment." : "Choose a scene to stage the presenter against its visual direction."}</p><div className="mt-6 flex justify-center gap-2"><Button data-testid="button-avatar-upload"><Upload size={14} /> Upload reference</Button><Button variant="secondary" data-testid="button-avatar-preview"><Play size={14} /> Preview delivery</Button></div></div></div></div></div></>; }

export function RenderPage() { const { data, isLoading, isError, refetch } = useListRenderJobs(); const create = useCreateRenderJob(); const cancel = useCancelRenderJob(); const queryClient = useQueryClient(); const projects = useListProjects(); const [projectId, setProjectId] = useState(""); const [preset, setPreset] = useState("preview"); const submit = () => { if (projectId) create.mutate({ data: { projectId: Number(projectId), preset: preset as any } }, { onSuccess: () => void queryClient.invalidateQueries() }); }; return <><PageHeader eyebrow="06 / render center" title="Render queue" description="Queue delivery jobs with explicit presets, progress, and recovery actions." action={<Button onClick={submit} disabled={!projectId || create.isPending} data-testid="button-queue-render"><Plus size={15} /> Queue render</Button>} /><div className="mb-7 grid gap-3 rounded-lg border border-border bg-card p-4 md:grid-cols-[1fr_220px_auto]"><select value={projectId} onChange={e => setProjectId(e.target.value)} className="h-10 rounded-md border border-input bg-background px-3 text-sm" data-testid="select-render-project"><option value="">Select a project to render</option>{(projects.data ?? []).filter((p: any) => p.status !== "archived").map((p: any) => <option key={p.id} value={p.id}>{p.name}</option>)}</select><select value={preset} onChange={e => setPreset(e.target.value)} className="h-10 rounded-md border border-input bg-background px-3 text-sm" data-testid="select-render-preset"><option value="preview">Preview · fast</option><option value="youtube">YouTube · 1080p</option><option value="shorts">Shorts · 9:16</option><option value="reels">Reels · 9:16</option><option value="master">Master · highest quality</option></select><Button onClick={submit} disabled={!projectId || create.isPending} data-testid="button-submit-render">{create.isPending ? "Queueing…" : "Add to queue"}</Button></div><QueryMessage isLoading={isLoading} isError={isError} refetch={refetch}>{data?.length ? <div className="space-y-3">{data.map((job: any) => <div key={job.id} className="rounded-lg border border-border bg-card p-5" data-testid={`row-render-job-${job.id}`}><div className="flex flex-col justify-between gap-4 md:flex-row md:items-center"><div className="flex min-w-0 items-center gap-4"><div className={`grid h-10 w-10 shrink-0 place-items-center rounded-md ${job.status === "rendering" ? "bg-primary/10 text-primary" : job.status === "complete" ? "bg-accent/10 text-accent" : "bg-muted text-muted-foreground"}`}><Film size={17} /></div><div className="min-w-0"><h3 className="truncate text-sm font-semibold">{job.projectName}</h3><p className="mt-1 font-mono text-[10px] uppercase tracking-wider text-muted-foreground">{job.preset} · job {String(job.id).padStart(4, "0")}</p></div></div><div className="flex items-center gap-4"><div className="text-right"><StatusPill status={job.status} />{job.eta && <p className="mt-2 font-mono text-[10px] text-muted-foreground">{job.eta} remaining</p>}</div>{job.status === "queued" || job.status === "rendering" ? <Button variant="ghost" onClick={() => cancel.mutate({ jobId: job.id }, { onSuccess: () => void queryClient.invalidateQueries() })} data-testid={`button-cancel-render-${job.id}`}><X size={15} /> Cancel</Button> : job.status === "failed" ? <Button variant="secondary" disabled data-testid={`button-retry-render-${job.id}`}><RefreshCw size={14} /> Retry</Button> : null}</div></div>{(job.status === "rendering" || job.status === "queued") && <div className="mt-4"><div className="h-1.5 overflow-hidden rounded-full bg-muted"><div className="h-full bg-primary transition-all duration-500" style={{ width: `${job.progress}%` }} /></div><div className="mt-2 flex justify-between font-mono text-[10px] text-muted-foreground"><span>{job.progress}% complete</span><span>{timeAgo(job.createdAt)}</span></div></div>}</div>)}</div> : <EmptyState title="Render queue is clear" detail="Choose a project and preset above when you are ready to stage delivery." />}</QueryMessage></>; }

export function SettingsPage() {
  const readiness = useGetSystemReadiness();
  const scan = useScanSystemReadiness();
  const pairingMutation = useCreateBridgePairing();
  const queryClient = useQueryClient();
  const [privacy, setPrivacy] = useState(true);
  const [pairing, setPairing] = useState<any>(null);
  const [credentialRequests, setCredentialRequests] = useState<Record<number, any>>({});
  const [performance, setPerformance] = useState([true, false]);
  const [copied, setCopied] = useState(false);
  const [browserOffline, setBrowserOffline] = useState(typeof navigator !== "undefined" && !navigator.onLine);
  const credentialPending = Object.values(credentialRequests).some((request: any) => request.status === "pending");
  const { data: providers, isLoading: providersLoading, isError: providersError, refetch: refetchProviders } = useListProviders({ query: { queryKey: getListProvidersQueryKey(), refetchInterval: credentialPending ? 2500 : false } });
  const credential = useRequestProviderCredential();
  const providerList = useMemo(() => providers ?? [], [providers]);

  useEffect(() => {
    const onOnline = () => setBrowserOffline(false);
    const onOffline = () => setBrowserOffline(true);
    window.addEventListener("online", onOnline);
    window.addEventListener("offline", onOffline);
    return () => { window.removeEventListener("online", onOnline); window.removeEventListener("offline", onOffline); };
  }, []);

  useEffect(() => {
    if (!providerList.length) return;
    setCredentialRequests(current => {
      let changed = false;
      const next = { ...current };
      providerList.forEach((provider: any) => {
        if (provider.tokenConfigured && current[provider.id]?.status === "pending") {
          next[provider.id] = { ...current[provider.id], status: "stored", detail: "The Mac worker confirmed this credential is stored in macOS Keychain." };
          changed = true;
        }
      });
      return changed ? next : current;
    });
  }, [providerList]);

  const invalidateReadiness = () => void queryClient.invalidateQueries({ queryKey: getGetSystemReadinessQueryKey() });
  const createPairing = () => pairingMutation.mutate(undefined, { onSuccess: (result: any) => { setPairing(result); invalidateReadiness(); } });
  const copyPairing = () => {
    if (!pairing?.pairingCode || !navigator.clipboard) return;
    void navigator.clipboard.writeText(pairing.pairingCode).then(() => { setCopied(true); window.setTimeout(() => setCopied(false), 1600); });
  };
  const requestCredential = (providerId: number) => credential.mutate({ providerId }, { onSuccess: (result: any) => { setCredentialRequests(current => ({ ...current, [providerId]: result })); void queryClient.invalidateQueries({ queryKey: getListProvidersQueryKey() }); } });
  const togglePerformance = (index: number) => setPerformance(current => current.map((enabled, itemIndex) => itemIndex === index ? !enabled : enabled));
  const report = readiness.data;
  const bridgeConnected = Boolean(report?.bridgeConnected);

  return <><PageHeader eyebrow="07 / settings" title="Runtime settings" description="Control the signed Mac worker, provider boundaries, and performance posture of this workstation." action={report?.bridgeConnected ? <div className="flex items-center gap-2 rounded-md border border-accent/20 bg-accent/5 px-3 py-2 text-xs text-accent"><span className="h-1.5 w-1.5 rounded-full bg-accent" /> Bridge connected</div> : <Link href="/settings#bridge" className="inline-flex items-center gap-2 rounded-md border border-primary/30 bg-primary/10 px-3 py-2.5 text-xs font-semibold text-primary" data-testid="link-settings-bridge-anchor"><KeyRound size={14} /> Set up bridge</Link>} />
    {browserOffline && <div className="mb-6 flex items-center gap-3 rounded-lg border border-destructive/25 bg-destructive/10 p-4" data-testid="status-browser-offline"><WifiOff size={17} className="text-red-200" /><p className="text-xs text-red-100">This browser is offline. Local bridge state may be stale; reconnect before pairing or requesting credentials.</p></div>}
    <div className="grid gap-6 xl:grid-cols-[1.1fr_.9fr]">
      <div className="space-y-6">
        <div id="bridge" className="rounded-lg border border-border bg-card p-5" data-testid="card-local-agent">
          <SectionLabel right={report && <StatusPill status={report.status} />}>Signed Mac worker</SectionLabel>
          {readiness.isLoading && <LoadingState rows={3} />}
          {!readiness.isLoading && readiness.isError && <div className="rounded-md border border-destructive/25 bg-destructive/10 p-4" data-testid="status-readiness-offline"><div className="flex items-start gap-3"><WifiOff size={17} className="mt-0.5 text-red-200" /><div><p className="text-sm font-semibold text-red-100">Worker is not responding</p><p className="mt-1 text-xs leading-relaxed text-red-100/70">The local service could not return a readiness report. Check that the Mac worker is running, then try again.</p></div></div><div className="mt-4 flex gap-2"><Button variant="danger" onClick={() => readiness.refetch()} data-testid="button-retry-readiness"><RefreshCw size={14} /> Retry connection</Button><Button variant="secondary" onClick={() => scan.mutate()} disabled={scan.isPending} data-testid="button-recovery-scan">{scan.isPending ? "Scanning…" : "Run recovery scan"}</Button></div></div>}
          {report && <><div className="flex flex-col gap-4 border-b border-border py-5 sm:flex-row sm:items-center"><div className={`grid h-12 w-12 shrink-0 place-items-center rounded-md border ${bridgeConnected ? "border-accent/30 bg-accent/10 text-accent" : "border-amber-300/30 bg-amber-300/10 text-amber-300"}`}><Cpu size={22} /></div><div className="min-w-0 flex-1"><h3 className="font-serif text-xl font-bold">{report.deviceName}</h3><p className="mt-1 text-xs text-muted-foreground">{report.chip} · {report.memory} · {report.accelerator}</p><p className="mt-1 font-mono text-[10px] text-muted-foreground">{bridgeConnected ? `${report.agent} · ${report.workerVersion ? `worker ${report.workerVersion}` : "version pending"}` : "No signed worker heartbeat"}</p></div><Button variant="secondary" onClick={() => scan.mutate(undefined, { onSuccess: invalidateReadiness })} disabled={scan.isPending} data-testid="button-scan-readiness"><RefreshCw size={14} className={scan.isPending ? "animate-spin" : ""} /> {scan.isPending ? "Scanning" : "Run scan"}</Button></div><div className="mt-5 grid grid-cols-2 gap-2 sm:grid-cols-4"><div className="rounded-md bg-background p-3"><p className="mono-label text-muted-foreground">Runtime</p><p className="mt-2 text-xs font-semibold">{report.runtime}</p></div><div className="rounded-md bg-background p-3"><p className="mono-label text-muted-foreground">Metal</p><p className="mt-2 text-xs font-semibold">{report.metal}</p></div><div className="rounded-md bg-background p-3"><p className="mono-label text-muted-foreground">MPS</p><p className="mt-2 text-xs font-semibold">{report.mps}</p></div><div className="rounded-md bg-background p-3"><p className="mono-label text-muted-foreground">MLX</p><p className="mt-2 text-xs font-semibold">{report.mlx}</p></div></div><div className="mt-3 grid gap-2 sm:grid-cols-2"><div className="rounded-md border border-border px-3 py-3"><p className="mono-label text-muted-foreground">Disk headroom</p><p className="mt-1 text-xs">{report.disk}</p></div><div className="rounded-md border border-border px-3 py-3"><p className="mono-label text-muted-foreground">Last worker signal</p><p className="mt-1 text-xs">{report.lastSeenAt ? timeAgo(report.lastSeenAt) : "No heartbeat recorded"}</p></div></div><div className="mt-5 grid gap-2">{report.checks.map((check: any) => <div key={check.name} className="flex items-center gap-3 rounded-md bg-background px-3 py-3" data-testid={`row-readiness-check-${check.name.toLowerCase().replaceAll(" ", "-")}`}><span className={check.status === "pass" ? "text-accent" : "text-amber-300"}>{check.status === "pass" ? <Check size={15} /> : <CircleAlert size={15} />}</span><div className="min-w-0 flex-1"><p className="text-xs font-medium">{check.name}</p><p className="text-[11px] text-muted-foreground">{check.detail}</p></div><StatusPill status={check.status} /></div>)}</div><div className="mt-5 border-t border-border pt-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="mono-label text-muted-foreground">Bridge identity</p><p className="mt-1 font-mono text-[11px] text-foreground">{report.bridgeId ?? "Not paired"}</p></div><span className="text-[11px] text-muted-foreground">{report.lastScanAt ? `Scanned ${timeAgo(report.lastScanAt)}` : "Scan not completed"}</span></div></div></>}
        </div>
        <div className="rounded-lg border border-border bg-card p-5" data-testid="card-bridge-pairing">
          <SectionLabel right={<span className="font-mono text-[10px] text-muted-foreground">one-time code</span>}>Pair this Mac</SectionLabel>
          <div className="flex flex-col gap-5 py-4 md:flex-row md:items-end"><div className="min-w-0 flex-1"><p className="text-sm font-semibold">Authorize the native worker</p><p className="mt-1 max-w-xl text-xs leading-relaxed text-muted-foreground">Generate a short-lived code, then enter it in the Local AI Studio worker on your Mac. The code is shown once and never becomes a reusable credential.</p>{pairing && <div className="mt-4 flex flex-wrap items-center gap-3"><code className="rounded-md border border-primary/30 bg-primary/[.08] px-4 py-3 font-mono text-xl font-bold tracking-[.22em] text-primary" data-testid="text-pairing-code">{pairing.pairingCode}</code><button onClick={copyPairing} className="inline-flex items-center gap-2 rounded-md border border-border px-3 py-2 text-xs font-semibold text-muted-foreground hover:bg-muted hover:text-foreground" data-testid="button-copy-pairing-code"><Copy size={14} /> {copied ? "Copied" : "Copy code"}</button><span className="w-full font-mono text-[10px] text-muted-foreground">{formatExpiry(pairing.expiresAt)} · do not share this code</span></div>}</div><Button onClick={createPairing} disabled={pairingMutation.isPending || browserOffline} data-testid="button-create-bridge-pairing"><KeyRound size={14} /> {pairingMutation.isPending ? "Generating…" : pairing ? "Generate new code" : "Generate pairing code"}</Button></div>{pairingMutation.isError && <p className="border-t border-border pt-3 text-xs text-red-200" data-testid="text-pairing-error">Could not generate a pairing code. Confirm the local service is running and try again.</p>}</div>
        <div className="rounded-lg border border-border bg-card p-5"><SectionLabel>Performance</SectionLabel>{[["Use unified memory efficiently", "Prefer local inference when memory allows"], ["Keep render workers warm", "Reduce startup time between queued jobs"]].map(([title, detail], i) => <div key={title} className="flex items-center justify-between border-b border-border py-4 last:border-0"><div><p className="text-sm font-semibold">{title}</p><p className="mt-1 text-xs text-muted-foreground">{detail}</p></div><button onClick={() => togglePerformance(i)} className={`relative h-6 w-11 rounded-full transition-colors ${performance[i] ? "bg-primary" : "bg-muted"}`} aria-pressed={performance[i]} data-testid={`button-toggle-performance-${i}`}><span className={`absolute top-1 h-4 w-4 rounded-full bg-foreground transition-transform ${performance[i] ? "translate-x-6" : "translate-x-1"}`} /></button></div>)}</div>
      </div>
      <div className="space-y-6">
        <div className="rounded-lg border border-border bg-card p-5"><SectionLabel>Privacy boundary</SectionLabel><div className="flex gap-3 border-b border-border py-5"><LockKeyhole className="mt-0.5 shrink-0 text-accent" size={18} /><div className="flex-1"><p className="text-sm font-semibold">Keep production data local</p><p className="mt-1 text-xs leading-relaxed text-muted-foreground">Scripts, presenter references, and voice profiles remain on this device unless a provider route is explicitly enabled.</p></div><button onClick={() => setPrivacy(!privacy)} className={`relative h-6 w-11 shrink-0 rounded-full ${privacy ? "bg-accent" : "bg-muted"}`} aria-pressed={privacy} data-testid="button-toggle-privacy"><span className={`absolute top-1 h-4 w-4 rounded-full bg-background transition-transform ${privacy ? "translate-x-6" : "translate-x-1"}`} /></button></div><p className="pt-4 font-mono text-[10px] uppercase tracking-wider text-accent">{privacy ? "Local-only boundary active" : "Review provider routes before continuing"}</p></div>
        <div><SectionLabel>Provider connections</SectionLabel>{credential.isError && <div className="mb-3 rounded-md border border-destructive/25 bg-destructive/10 p-3 text-xs text-red-200" data-testid="status-credential-request-error">The Mac worker could not start the secure credential request. Confirm the bridge is connected and try again.</div>}<QueryMessage isLoading={providersLoading} isError={providersError} refetch={refetchProviders}><div className="space-y-2">{(providers ?? []).map((provider: any) => { const request = credentialRequests[provider.id]; const isHuggingFace = provider.kind === "huggingface"; const storageLabel = provider.credentialStorage === "macos-keychain" && provider.tokenConfigured ? "Stored in macOS Keychain · value hidden" : provider.tokenConfigured ? "Credential present · value hidden" : "No credential stored"; return <div key={provider.id} className="rounded-lg border border-border bg-card p-4" data-testid={`card-settings-provider-${provider.id}`}><div className="flex items-start gap-3"><Server size={16} className="mt-0.5 text-muted-foreground" /><div className="min-w-0 flex-1"><p className="text-sm font-semibold">{provider.name}</p><p className="mt-1 text-xs text-muted-foreground">{provider.detail}</p></div><StatusPill status={provider.status} /></div><div className="mt-4 flex flex-wrap items-center justify-between gap-3 border-t border-border pt-3"><span className="font-mono text-[10px] text-muted-foreground">{storageLabel}</span>{isHuggingFace && <Button variant={request?.status === "stored" ? "ghost" : "secondary"} onClick={() => requestCredential(provider.id)} disabled={!bridgeConnected || credential.isPending || request?.status === "pending"} title={!bridgeConnected ? "Pair the Mac worker first" : "Ask the Mac worker to collect this credential"} data-testid={`button-settings-provider-${provider.id}`}>{request?.status === "stored" ? <><Check size={14} /> Credential stored</> : request?.status === "pending" ? <><RefreshCw size={14} className="animate-spin" /> Waiting for Mac</> : <><KeyRound size={14} /> {credential.isPending ? "Requesting…" : bridgeConnected ? "Store in Keychain" : "Pair bridge first"}</>}</Button>}</div>{request && <div className={`mt-3 rounded-md border p-3 text-xs ${request.status === "stored" ? "border-accent/20 bg-accent/[.06] text-accent" : request.status === "failed" ? "border-destructive/25 bg-destructive/10 text-red-200" : "border-primary/20 bg-primary/[.06] text-primary"}`} data-testid={`status-credential-request-${provider.id}`}><p className="font-semibold">{request.status === "stored" ? "Credential storage confirmed" : request.status === "failed" ? "Credential storage failed" : "Credential request sent to the Mac"}</p><p className="mt-1 opacity-80">{request.detail}</p></div>}</div>; })}</div></QueryMessage><p className="mt-3 text-[11px] leading-relaxed text-muted-foreground">Hugging Face credentials are collected by the native worker and stored in macOS Keychain. This studio never accepts, displays, or transmits the token.</p></div>
      </div>
    </div>
  </>;
}
